class AllocContext
{
    public nint Ptr;    // alloc_ptr: начало свободного места
    public nint Limit;  // alloc_limit: конец порции

    public nint TryAlloc(int size)
    {
        nint end = Ptr + size;
        if (end > Limit) return 0;  // не влезло: медленный путь
        nint obj = Ptr;
        Ptr = end;                  // весь «поиск места»
        return obj;
    }
}
